class CodeMirrorLint {
    constructor(restClient) {
        this.restClient = restClient;
        this.currentRequest = null;
    }

    async execute(doc) {
        // Abort any previous request
        if (this.currentRequest) {
            this.currentRequest.abort();
        }

        try {
            // Create a new request
            const controller = new AbortController();
            this.currentRequest = controller;

            const response = await this.restClient.post('/v1/transform/wikitext/to/lint', {
                wikitext: doc.toString()
            }, { signal: controller.signal });

            // Reset the current request reference
            this.currentRequest = null;

            return response.data;
        } catch (error) {
            if (error.name === 'AbortError') {
                mw.log.warn('[CodeMirror] Request aborted.');
            } else {
                mw.log.error('[CodeMirror] Error during linting:', error);
            }
            throw error;
        }
    }
}
```

