/**
 * Remaps search queries based on predefined rules.
 *
 * @param string $searchQuery The search query to be remapped.
 * @return string|null The remapped search query or null if no mapping is found.
 */
public function remapSearchQuery(string $searchQuery): ?string {
    // Define the mapping rules
    $remappingRules = [
        'old-query' => 'new-query',
        'another-old-query' => 'another-new-query'
    ];

    // Check if the search query matches any rule
    foreach ($remappingRules as $oldQuery => $newQuery) {
        if (str_starts_with($searchQuery, $oldQuery)) {
            return $newQuery;
        }
    }

    // Return null if no matching rule is found
    return null;
}
