class Entity {
    private $qualOrRefUsageTrackingEnabled;

    public function __construct($qualOrRefUsageTrackingEnabled) {
        $this->qualOrRefUsageTrackingEnabled = $qualOrRefUsageTrackingEnabled;
    }

    public function getEntityStatements($propertyId, $entity) {
        if ($propertyId && isset($entity->claims[$propertyId])) {
            $statements = $entity->claims[$propertyId];
            $originalStatements = $statements;

            if ($this->qualOrRefUsageTrackingEnabled) {
                foreach ($statements as &$statement) {
                    unset($statement['qualifiers']);
                    unset($statement['references']);
                }
            }

            $cloneOfStatements = mw.clone($statements);

            if ($this->qualOrRefUsageTrackingEnabled) {
                foreach ($cloneOfStatements as $cloneKey => &$cloneOfStatement) {
                    $cloneOfStatement['qualifiers'] = $originalStatements[$cloneKey]['qualifiers'];
                    $cloneOfStatement['references'] = $originalStatements[$cloneKey]['references'];
                }
            }

            return $cloneOfStatements;
        }

        return [];
    }
}
