/**
 * Creates a new XML element with the specified attributes and children.
 *
 * @param string $name The name of the new element.
 * @param array<string,string> $attribs An associative array of attribute names and their corresponding values.
 * @param Node|string ...$children A list of child nodes for the new element. Strings are converted to new text nodes before their insertion into the tree.
 */
public function createXmlElement(string $name, array $attribs, ...$children): Node {
    // Create the new element node
    $element = $this->dom->createElement($name);

    // Set attributes for the element
    foreach ($attribs as $attrName => $attrValue) {
        $element->setAttribute($attrName, htmlspecialchars($attrValue));
    }

    // Append child nodes to the element
    foreach ($children as $child) {
        if (is_string($child)) {
            $childNode = $this->dom->createTextNode(htmlspecialchars($child));
        } else {
            $childNode = $child;
        }
        $element->appendChild($childNode);
    }

    return $element;
}
